using System.ComponentModel;
using System.Globalization;
using System.Runtime.CompilerServices;
using System.Windows.Input;

public abstract class ViewModelBase : INotifyPropertyChanged
{
    public event PropertyChangedEventHandler? PropertyChanged;

    protected void Raise([CallerMemberName] string? name = null) =>
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));

    protected bool Set<T>(ref T field, T value, [CallerMemberName] string? name = null)
    {
        if (EqualityComparer<T>.Default.Equals(field, value)) return false;
        field = value;
        Raise(name);
        return true;
    }
}

public sealed class RelayCommand(Action execute, Func<bool> canExecute) : ICommand
{
    public event EventHandler? CanExecuteChanged;
    public bool CanExecute(object? parameter) => canExecute();
    public void Execute(object? parameter) { if (CanExecute(parameter)) execute(); }
    public void NotifyCanExecuteChanged() => CanExecuteChanged?.Invoke(this, EventArgs.Empty);
}

public sealed class TipViewModel : ViewModelBase
{
    private string _billText = "";
    private int _tipPercent = 15;
    private int _people = 1;

    public TipViewModel()
    {
        AddPersonCommand = new RelayCommand(() => People++, () => true);
        RemovePersonCommand = new RelayCommand(() => People--, () => People > 1);
        ResetCommand = new RelayCommand(() => { BillText = ""; TipPercent = 15; People = 1; }, () => true);
    }

    public RelayCommand AddPersonCommand { get; }
    public RelayCommand RemovePersonCommand { get; }
    public RelayCommand ResetCommand { get; }

    public string BillText
    {
        get => _billText;
        set { if (Set(ref _billText, value)) RaiseComputed(); }
    }

    public int TipPercent
    {
        get => _tipPercent;
        set { if (Set(ref _tipPercent, Math.Clamp(value, 0, 30))) RaiseComputed(); }
    }

    public int People
    {
        get => _people;
        set
        {
            if (!Set(ref _people, Math.Max(1, value))) return;
            RaiseComputed();
            RemovePersonCommand.NotifyCanExecuteChanged();
        }
    }

    private decimal? Bill =>
        decimal.TryParse(_billText, NumberStyles.Number, CultureInfo.InvariantCulture, out var b) && b > 0 ? b : null;

    private static decimal Cents(decimal x) => Math.Round(x, 2, MidpointRounding.AwayFromZero);
    private static string Show(decimal x) => x.ToString("F2", CultureInfo.InvariantCulture);

    public string Total => Bill is decimal b ? Show(Cents(b * (1 + _tipPercent / 100m))) : "";
    public string PerPerson => Bill is decimal b ? Show(Cents(Cents(b * (1 + _tipPercent / 100m)) / _people)) : "";
    public string Error => Bill is null ? "Enter the bill amount" : "";

    private void RaiseComputed()
    {
        Raise(nameof(Total));
        Raise(nameof(PerPerson));
        Raise(nameof(Error));
    }
}

