List<string> Watch(TipViewModel vm)
{
    var names = new List<string>();
    vm.PropertyChanged += (_, e) => names.Add(e.PropertyName!);
    return names;
}

Test("starting state", () =>
{
    var vm = new TipViewModel();
    CheckEq((vm.BillText, vm.TipPercent, vm.People), ("", 15, 1));
    CheckEq((vm.Total, vm.PerPerson, vm.Error), ("", "", "Enter the bill amount"));
    CheckEq(vm.RemovePersonCommand.CanExecute(null), false);
});

Test("calculating", () =>
{
    var vm = new TipViewModel();
    vm.BillText = "50";
    CheckEq((vm.Total, vm.PerPerson, vm.Error), ("57.50", "57.50", ""));
    vm.People = 3;
    CheckEq(vm.PerPerson, "19.17");
    vm.TipPercent = 10;
    CheckEq(vm.Total, "55.00");
    vm.BillText = "12.345";
    CheckEq(vm.Total, "13.58");
    vm.BillText = "-5";
    CheckEq((vm.Total, vm.Error), ("", "Enter the bill amount"));
});

Test("change notifications", () =>
{
    var vm = new TipViewModel();
    var names = Watch(vm);
    vm.BillText = "20";
    CheckEq(names, new[] { "BillText", "Total", "PerPerson", "Error" });
    names.Clear();
    vm.BillText = "20";
    CheckEq(names.Count, 0);
    vm.TipPercent = 99;
    CheckEq(vm.TipPercent, 30);
    CheckEq(names, new[] { "TipPercent", "Total", "PerPerson", "Error" });
    names.Clear();
    vm.TipPercent = 45;
    CheckEq(names.Count, 0);
});

Test("commands", () =>
{
    var vm = new TipViewModel();
    int canChanged = 0;
    vm.RemovePersonCommand.CanExecuteChanged += (_, _) => canChanged++;
    vm.AddPersonCommand.Execute(null);
    vm.AddPersonCommand.Execute(null);
    CheckEq(vm.People, 3);
    CheckEq(vm.RemovePersonCommand.CanExecute(null), true);
    vm.RemovePersonCommand.Execute(null);
    vm.RemovePersonCommand.Execute(null);
    vm.RemovePersonCommand.Execute(null);
    CheckEq(vm.People, 1);
    CheckEq(canChanged, 4);
    vm.People = 0;
    CheckEq(vm.People, 1);
    vm.BillText = "10"; vm.TipPercent = 0; vm.People = 4;
    vm.ResetCommand.Execute(null);
    CheckEq((vm.BillText, vm.TipPercent, vm.People, vm.Total), ("", 15, 1, ""));
});

